<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'; import { useRoute } from 'vue-router'; import { api } from '../api/client'; import { money } from '../format'
const id=String(useRoute().params.id);const activity=ref<any>();const participants=ref<any[]>([]);const expenses=ref<any[]>([]);const bill=ref<any>();const preview=ref<any>();const error=ref('');const amount=ref('');const description=ref('球钱');const kind=ref('shuttle');const payer=ref('');const canPublish=computed(()=>activity.value?.is_host&&(activity.value.status==='finished'||activity.value.status==='cancelled')&&activity.value.billing_status==='draft');onMounted(load)
async function load(){activity.value=await api(`/activities/${id}`);participants.value=(await api<any>(`/activities/${id}/participants`)).items;expenses.value=(await api<any>(`/activities/${id}/expenses`)).items;payer.value=activity.value.my_participant_id;try{bill.value=await api(`/activities/${id}/bill`)}catch{}try{preview.value=await api(`/activities/${id}/bill/preview`)}catch(e){error.value=e instanceof Error?e.message:''}}
function cents(value:string){if(!/^\d+(\.\d{1,2})?$/.test(value))throw new Error('金额最多保留两位小数');const [yuan,fen='']=value.split('.');return Number(yuan)*100+Number(fen.padEnd(2,'0'))}
async function add(){error.value='';try{await api(`/activities/${id}/expenses`,{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({kind:kind.value,description:description.value,amount_cents:cents(amount.value),payer_participant_id:payer.value,split_mode:'equal',split_scope:'attendees',shares:[]})});amount.value='';await load()}catch(e){error.value=e instanceof Error?e.message:'记录失败'}}
async function publish(){bill.value=await api(`/activities/${id}/bill/publish`,{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({expected_generation:activity.value.bill_generation})});await load()}
async function claim(t:any){await api(`/activities/${id}/payments`,{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({bill_revision_id:bill.value.id,transfer_id:t.id,amount_cents:t.amount_cents})});await load()}
async function confirm(p:any){await api(`/activities/${id}/payments/${p.id}/confirm`,{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()}});await load()}
</script>
<template><section class="shell page"><div class="page-head"><div><p class="eyebrow">个人账单</p><h1>{{activity?.title||'本场费用'}}</h1><p class="muted">付款声明需由指定收款人确认，确认后才会冲抵欠款。</p></div><button v-if="canPublish" class="primary" @click="publish">发布账单</button></div><div class="bill-layout"><div class="stack"><article v-if="bill" class="card personal"><p class="eyebrow">你的账款</p><h2 v-if="bill.my_summary.balance_cents<0">你还需支付 {{money(-bill.my_summary.balance_cents)}}</h2><h2 v-else-if="bill.my_summary.balance_cents>0">你还应收 {{money(bill.my_summary.balance_cents)}}</h2><h2 v-else>你的账已经结清</h2><div v-for="t in bill.my_summary.outgoing" :key="t.id" class="transfer"><span>向 {{bill.snapshot.participant_snapshots.find((p:any)=>p.id===t.to_participant_id)?.name}} 支付</span><strong>{{money(t.amount_cents)}}</strong><button @click="claim(t)">我已付</button></div><div v-for="p in bill.payment_claims.filter((p:any)=>p.status==='claimed')" :key="p.id" class="transfer"><span>付款声明 {{p.short_code}}</span><strong>{{money(p.amount_cents)}}</strong><button @click="confirm(p)">确认收款</button></div></article><article class="card"><h2>费用明细</h2><div v-if="expenses.length"><div v-for="expense in expenses" :key="expense.id" class="expense"><span>{{expense.description}} <small>{{expense.short_code}}</small></span><strong>{{money(expense.amount_cents)}}</strong></div><div class="expense total"><strong>合计</strong><strong>{{money(expenses.reduce((n,e)=>n+e.amount_cents,0))}}</strong></div></div><div v-else class="empty"><p class="muted">还没有实际支出。</p></div></article><article v-if="preview&&!bill" class="card"><h2>账单预览</h2><p class="big-money">{{money(preview.total_cents)}}</p><p class="muted">{{preview.transfers.length}} 笔球友间转账</p></article></div><aside v-if="activity?.billing_status==='draft'" class="card stack"><div><p class="eyebrow">记一笔费用</p><h2>只记录已经实际支付的金额</h2></div><label>类型<select v-model="kind"><option value="venue">场地费</option><option value="shuttle">球钱</option><option value="extra">其他 AA</option></select></label><label>说明<input v-model="description"></label><label>金额（元）<input v-model="amount" inputmode="decimal" autofocus placeholder="0.00"></label><label>垫付人<select v-model="payer"><option v-for="p in participants" :key="p.id" :value="p.id">{{p.display_name}}</option></select></label><button class="primary" :disabled="!amount" @click="add">记录费用</button><p v-if="error" class="error">{{error}}</p></aside></div><div v-if="canPublish" class="mobile-action"><button class="primary" @click="publish">发布账单</button></div></section></template>
<style scoped>.bill-layout{display:grid;grid-template-columns:minmax(0,2fr) minmax(280px,1fr);gap:20px}.personal h2{font-size:32px;line-height:1.25}.expense,.transfer{display:grid;grid-template-columns:1fr auto auto;gap:12px;align-items:center;padding:13px 0;border-top:1px solid var(--line)}.expense strong,.transfer strong{text-align:right}.expense small{color:var(--muted)}.expense.total{font-size:18px}.big-money{font-size:32px;font-weight:750}@media(max-width:720px){.bill-layout{grid-template-columns:1fr}.bill-layout aside{order:-1}.transfer{grid-template-columns:1fr auto}.transfer button{grid-column:1/-1}}</style>

